"""Fixed English contracts; no scene-specific teaching answers."""
import json


def obj(properties):
    return {'type':'object','properties':properties,'required':list(properties),'additionalProperties':False}


TEXT = {'type':'string'}
STRINGS = {'type':'array','items':TEXT}
STAGE = obj({'stage_id':{'type':'integer'},'title':TEXT,'targets':STRINGS,'completed_scope':TEXT})
PLAN = obj({'rationale':TEXT,'stages':{'type':'array','items':STAGE,'minItems':4,'maxItems':5}})
IMPLEMENTATION = obj({'finding_id':TEXT,'status':{'type':'string','enum':['implemented','partially_implemented','not_implemented','not_applicable']},'actual_change':TEXT,'code_evidence':TEXT})
PATCH = obj({'decision':{'type':'string','enum':['apply','decline']},'code':TEXT,'reason':TEXT,'changes':TEXT,'advice_implementation':{'type':'array','items':IMPLEMENTATION},'completed_scope':TEXT})
FINDING = obj({'id':TEXT,'target':TEXT,'problem_source':TEXT,'rule_source':TEXT,'reference_evidence':TEXT,'render_evidence':TEXT,'proposed_change':TEXT,'preserve':TEXT,'check_after':TEXT,'uncertainty':TEXT,'status':{'type':'string','enum':['new','resolved','partially_resolved','unresolved','cannot_determine','not_applicable']}})
REVIEW = obj({'decision':{'type':'string','enum':['revise','advance','advance_with_issue']},'findings':{'type':'array','items':FINDING,'maxItems':3},'summary':TEXT})
RULE = obj({'rule_id':TEXT,'rule':TEXT,'origin':{'type':'string','enum':['development_derived','preexisting_general_rule']},'evidence':{'type':'array','items':obj({'stage_id':{'type':'integer'},'feedback_id':TEXT,'observed_issue':TEXT,'actual_student_change':TEXT,'outcome_and_limit':TEXT})},'applicability_limit':TEXT})
EXTRACTION = obj({'policy_markdown':TEXT,'student_self_review_py':TEXT,'lesson_provenance':{'type':'array','items':RULE,'minItems':5,'maxItems':8},'not_transferred':STRINGS,'limitations':TEXT})

COMMON = '''All model-facing input and all natural-language output must be English.
Reconstruct the attached reference as editable three-dimensional geometry. Use only the staged images and supplied context. Do not call tools, run Blender, access files, use external models, or inspect other tasks. The fixed runner alone executes code and supplies actual renders. Do not use reference imagery as a texture, background, projection, or flat reproduction. No automatic quality scores. Hidden geometry has no unique ground truth.
The scene persists within this task. The first patch initializes it; later patches operate on the loaded previous .blend. Python variables and functions from earlier patches DO NOT persist; named Blender objects, materials and object IDs DO persist. Import required modules and define local helpers in each patch. Use stable names and edit existing objects through bpy; do not rebuild the entire scene. SceneAct realize(new_scene, clear=False) can append new groups. Initial realize(scene) is allowed only when no checkpoint exists. Never delete all prior objects, call reset/read_factory_settings/open/save/render, change render resolution/samples/device/threads, read files, or use network. Fixed CPU Cycles settings are outside your control.
Use compact geometry, meaningful object and part names, and parent related parts. Make only the current stage's meaningful additions; do not finish the entire scene in stage one. Preserve already completed unrelated objects and camera unless the actual evidence warrants changing them. Coordinates are scene units, not measured real-world dimensions.
'''

PLAN_INSTRUCTION = '''Plan four or five ordered, meaningful stages for THIS image. Start with the environment, camera and basic lighting; then major furniture/object groups; then secondary objects/relations; then appearance and a final global check. Adapt grouping to the actual image. Each stage has a contiguous stage_id starting at 1, short title, target groups and completed_scope (what should exist by the end). This call does not build anything. No teacher guidance is available before the first actual build. Return the plan JSON only.'''

PATCH_INSTRUCTION = '''Write one incremental Python patch for the current stage/feedback, not a replacement whole-scene program. Return PATCH JSON. decision=apply requires complete executable patch code, including imports. decision=decline requires empty code and a specific reason. For each supplied feedback finding, state implemented/partially_implemented/not_implemented/not_applicable and point to actual code changes; these are your claims awaiting the next real render, not verified success. Do not claim a new result has been observed before the runner executes it. There is at most one visual correction patch and one additional technical-error repair per stage. Technical repair does not substitute for an actual visual review. Do not use further calls or rendering inside the CLI.'''

TEACHER = '''You are the DEVELOPMENT teacher. All output is English. You provide brief natural-language feedback only; never write scene code or change the scene. Attachment 1 is the current task's reference, attachment 2 is the actual current render; attachment 3, if supplied, is the previous checkpoint render. Review only completed stage content and its dependencies: do not penalize objects scheduled for a future stage. Identify zero to three important issues with direct reference/render evidence, target objects/relationships, what to change, what to preserve, what to check afterward, and uncertainty. Never infer unique focal length or physical dimensions from a single view. Record requested extra views in uncertainty; do not pretend unavailable views were observed.
Return the REVIEW schema. problem_source=development_observation; rule_source=teacher_observation. Choose revise if one visual correction is available and useful, advance if ready, or advance_with_issue if unresolved within the budget. On verification, judge the actual changed image, mark findings resolved/partially_resolved/unresolved/cannot_determine as supported, and never request another patch beyond the single correction. This is process feedback, not an external quality score or guarantee of faithful geometry.'''

SELF_REVIEW_CONTRACT = '''You are the SAME fixed student model reviewing your current TEST scene. All output must be English. There is no teacher in this task. Attachment 1 is the test reference and attachment 2 is your actual current render; optional attachment 3 is the previous checkpoint. Follow the frozen general policy below, but discover issues from these TEST images rather than restating a development lesson as a new finding.
Return REVIEW JSON: zero to three findings, each problem_source=test_observation, rule_source=a frozen rule ID or student_prior_judgment, and concrete reference_evidence/render_evidence. Distinguish new, resolved, partially_resolved, unresolved, cannot_determine or not_applicable. proposed_change is a proposal; actual changes are recorded only after the student patch and Blender execution. Review only currently completed content. No score, no teacher role, no external tools. Choose revise only while the one visual correction is available; otherwise advance or advance_with_issue. On verification read the actual new result and previous findings; no additional patch cycle.'''

DISTILL = '''You are extracting a STUDENT SELF-CHECK PROCEDURE from this development task only. All outputs English. You have no access to the test image, task, generated scene, or answers. Produce five to eight brief general rules, a pure Python entry, and provenance linking each rule to real supplied development observations, feedback IDs, actual patches and post-patch outcomes. Separate preexisting_general_rule from development_derived; unsupported, retracted or scene-specific advice belongs in not_transferred. Do not invent evidence or claim quality gain.
Do NOT carry scene-specific object names, counts, colors, coordinates, source IDs, paths, images or construction answers into the policy/code. Provenance may describe the development evidence but is NOT provided to the test student. Rules should be general questions/measurements that the student answers using current test evidence.
The single Python entry is build_review_prompt(context). It returns an English prompt STRING incorporating the frozen rules and json.dumps(context); it is actually invoked before every test review/verification. You may import json only and define small pure helpers; no file access, external calls, runtime mutation, eval/exec, or task-specific branches. Context has stage, completed_scope, inventory, previous_findings, verification, visual_correction_available, operation. Return fields policy_markdown, student_self_review_py (complete source), lesson_provenance, not_transferred, limitations. This is language strategy extraction, not weight distillation, teacher evolution or verified capability improvement.'''


def context_text(context):
    return '\nEXPLICIT CONTEXT:\n'+json.dumps(context,ensure_ascii=False,indent=2)
